#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Dois fixes independentes reportados juntos:

1) FATAL EXCEPTION main -- NoSuchMethodError: createWindowContext
   (Display, int, Bundle) em DisplayControllerImpl.kt, no Android 11.
   Bug PRE-EXISTENTE ao projeto de customizacoes (nao e regressao de
   nada que fizemos). createWindowContext(Display, int, Bundle) --
   a variante com Display explicito -- so existe a partir da API 31
   (Android 12); no Android 11 (API 30) essa assinatura de 3
   argumentos nao existe na classe Context, e o codigo chamava ela
   incondicionalmente, derrubando o app logo no Launcher.onCreate(),
   antes de qualquer tela aparecer. Fix: em API 30, usa
   createDisplayContext(display) + createWindowContext(int, Bundle) --
   a combinacao documentada pela propria Android para obter um window
   context de um display especifico quando so a variante de 2
   argumentos esta disponivel.

2) "Nao aplicou cor nenhuma" -- bug real na propria feature UI-UX
   Custom Colors, mesmo apos o fix do crash do BroadcastReceiver.
   XaulinXsThemedContextWrapper so sobrescrevia getResources(), mas a
   maioria do codigo real do Launcher3 chama
   context.getColor(R.color.materialColorX) diretamente (nao
   resources.getColor(id)). Context.getColor()/getColorStateList() em
   ContextWrapper simplesmente delegam para o Context "base" original
   -- nao passam por this.getResources() -- entao a cor nunca era
   interceptada nesse caminho. Fix: sobrescrever getColor()/
   getColorStateList() tambem no ContextWrapper, nao so no Resources.

Arquivos substituidos por completo (mudanca concentrada e/ou
espalhada em varios blocos de comentario):
  src/com/android/launcher3/display/DisplayControllerImpl.kt
  modules/customizations/.../theme/XaulinXsThemeColorResources.kt

Rode este script na RAIZ do checkout local do repo (mesmo diretorio do
gradlew), dentro do Termux.

python3 fix_display_and_color_apply.py

Idempotente.
"""
import base64
import sys
from pathlib import Path

def die(msg):
    print("ERRO:", msg)
    sys.exit(1)

if not Path("gradlew").exists():
    die("rode este script na raiz do checkout (onde esta o gradlew).")

FILES = {
    "src/com/android/launcher3/display/DisplayControllerImpl.kt": (
        '',
        'createWindowContextCompat',
    ),
    "modules/customizations/src/com/xaulinxs/customizations/theme/XaulinXsThemeColorResources.kt": (
        '',
        'XaulinXs fix: sobrescrever só getResources() não bastava',
    ),
}

updated, skipped = [], []
for rel_path, (b64, marker) in FILES.items():
    target = Path(rel_path)
    if not target.exists():
        die(f"nao encontrei {rel_path}. Voce ja rodou os scripts anteriores (apply_custom_colors.py etc.)?")

    new_content = base64.b64decode(b64).decode("utf-8")
    current_content = target.read_text(encoding="utf-8")

    if marker in current_content:
        skipped.append(rel_path)
        continue

    target.write_text(new_content, encoding="utf-8")
    updated.append(rel_path)

print()
if updated:
    print("Arquivos corrigidos:")
    for p in updated:
        print("  ~", p)
if skipped:
    print("Ja corrigidos (pulados):")
    for p in skipped:
        print("  =", p)

if not updated:
    print()
    print("Ja aplicado -- nada a fazer.")
else:
    print()
    print("OK: os dois fixes foram aplicados.")
    print("Agora: git add -A && git commit -m 'fix: crash Android 11 (createWindowContext) + cor nao aplicava (Context.getColor)' && git push")
    print("Depois: ./gradlew assembleNoQuickstepDebug")
